    // ──────────────────────────────────────────────────────────────
    //  Reference tests: compare our output against ONNX Runtime ground truth
    //  Generated by tools/gen_references.py using onnxruntime 1.24.3
    // ──────────────────────────────────────────────────────────────

    /// <summary>Helper: load float32 binary and run inference, return output floats.</summary>
    private async Task<(float[] actual, float[] expected)> RunReferenceComparison(
        Accelerator accelerator, string modelPath, string inputRefPath, string outputRefPath,
        int[] inputShape)
    {
        var http = GetHttpClient();
        if (http == null) throw new UnsupportedTestException("HttpClient not available");

        var inputBytes = await http.GetByteArrayAsync(inputRefPath);
        var inputFloats = new float[inputBytes.Length / 4];
        Buffer.BlockCopy(inputBytes, 0, inputFloats, 0, inputBytes.Length);

        var outputBytes = await http.GetByteArrayAsync(outputRefPath);
        var expected = new float[outputBytes.Length / 4];
        Buffer.BlockCopy(outputBytes, 0, expected, 0, outputBytes.Length);

        using var session = await InferenceSession.CreateFromFileAsync(accelerator, http, modelPath);
        using var inputBuf = accelerator.Allocate1D(inputFloats);
        var inputTensor = new Tensor(inputBuf.View, inputShape);

        var outputs = await session.RunAsync(new Dictionary<string, Tensor>
        {
            [session.InputNames[0]] = inputTensor
        });

        var output = outputs[session.OutputNames[0]];
        int elems = output.ElementCount;
        using var readBuf = accelerator.Allocate1D<float>(elems);
        new ElementWiseKernels(accelerator).Scale(output.Data.SubView(0, elems), readBuf.View, elems, 1f);
        await accelerator.SynchronizeAsync();
        var actual = await readBuf.CopyToHostAsync<float>(0, elems);

        return (actual, expected);
    }

    /// <summary>
    /// GPU-side reference comparison — keeps all data on GPU. Only 2 floats read back to CPU.
    /// </summary>
    private async Task RunReferenceComparisonGpu(
        Accelerator accelerator, string modelPath, string inputRefPath, string outputRefPath,
        int[] inputShape, float maxMeanErr, string name)
    {
        var http = GetHttpClient();
        if (http == null) throw new UnsupportedTestException("HttpClient not available");

        var inputBytes = await http.GetByteArrayAsync(inputRefPath);
        var inputFloats = new float[inputBytes.Length / 4];
        Buffer.BlockCopy(inputBytes, 0, inputFloats, 0, inputBytes.Length);

        var outputBytes = await http.GetByteArrayAsync(outputRefPath);
        var expected = new float[outputBytes.Length / 4];
        Buffer.BlockCopy(outputBytes, 0, expected, 0, outputBytes.Length);

        using var session = await InferenceSession.CreateFromFileAsync(accelerator, http, modelPath);
        using var inputBuf = accelerator.Allocate1D(inputFloats);
        var inputTensor = new Tensor(inputBuf.View, inputShape);

        var outputs = await session.RunAsync(new Dictionary<string, Tensor>
        {
            [session.InputNames[0]] = inputTensor
        });

        // Compare on GPU — expected stays on GPU, actual stays on GPU, only 2 floats come back
        var output = outputs[session.OutputNames[0]];
        int elems = Math.Min(output.ElementCount, expected.Length);
        using var expectedBuf = accelerator.Allocate1D(expected);
        await AssertReferenceMatchGpu(accelerator, output.Data.SubView(0, elems), expectedBuf.View.SubView(0, elems), elems, maxMeanErr, name);
    }

    /// <summary>Helper: assert mean error within threshold.</summary>
    private static void AssertReferenceMatch(float[] actual, float[] expected, float maxMeanErr, string name)
    {
        if (actual.Length != expected.Length)
            throw new Exception($"[{name}] Size mismatch: actual={actual.Length}, expected={expected.Length}");

        double sumErr = 0;
        float maxErr = 0;
        for (int i = 0; i < expected.Length; i++)
        {
            float err = MathF.Abs(actual[i] - expected[i]);
            sumErr += err;
            if (err > maxErr) maxErr = err;
        }
        float meanErr = (float)(sumErr / expected.Length);

        if (meanErr > maxMeanErr)
        {
            var a5 = string.Join(",", actual.Take(5).Select(v => v.ToString("F2")));
            var e5 = string.Join(",", expected.Take(5).Select(v => v.ToString("F2")));
            throw new Exception($"[{name}] Mean error {meanErr:F4} > {maxMeanErr}. actual=[{a5}] expected=[{e5}]");
        }
    }

    /// <summary>
    /// GPU-side reference match — compares two GPU buffers entirely on-device.
    /// Only 2 floats read back to CPU (meanError, maxError). No large readbacks.
    /// </summary>
    private static async Task AssertReferenceMatchGpu(
        Accelerator accelerator,
        ArrayView1D<float, Stride1D.Dense> actual,
        ArrayView1D<float, Stride1D.Dense> expected,
        int count, float maxMeanErr, string name)
    {
        var ew = new ElementWiseKernels(accelerator);
        var (meanErr, maxErr) = await ew.CompareOnGpuAsync(actual, expected, count);
        Console.WriteLine($"[{name}] GPU verify: meanErr={meanErr:F4}, maxErr={maxErr:F4}");
        if (meanErr > maxMeanErr)
            throw new Exception($"[{name}] Mean error {meanErr:F4} > {maxMeanErr}");
    }

    // ── MoveNet Reference Test ──

    /// <summary>
    /// MoveNet Lightning vs ONNX Runtime 1.24.3 ground truth on the cat reference image.
    /// References at wwwroot/references/movenet-lightning/ : cat_input_nhwc_int32.bin
    /// (192*192*3 = 110592 int32 [0,255] values) and cat_output.bin (51 float32 keypoint values
    /// in [y,x,conf] x 17 layout).
    ///
    /// 2026-05-23: this test exists specifically to catch the broken-inference regression we
    /// hit after shipping pose as "verified" - the unit test that gated the verification claim
    /// (CreateFromFile_MoveNet_Inference) only required >=1 keypoint conf > 0.05, which was
    /// trivially satisfied by a single saturated 1.0 spike from un-clipped Relu6 activations.
    /// Comparing against ORT's actual keypoint coordinates+confidences is the real bar.
    /// </summary>
    [TestMethod(Timeout = 180000)]
    public async Task Reference_MoveNetLightning_MatchesOnnxRuntime() => await RunTest(async accelerator =>
    {
        var http = GetHttpClient();
        if (http == null) throw new UnsupportedTestException("HttpClient not available");

        // Input is int32 NHWC [0,255] - the model takes int32 then internally Casts to float.
        // We have an all-float pipeline so feed as floats with identical numeric values.
        var inputInt32Bytes = await http.GetByteArrayAsync("references/movenet-lightning/cat_input_nhwc_int32.bin");
        int elemCount = inputInt32Bytes.Length / 4;
        var inputFloats = new float[elemCount];
        for (int i = 0; i < elemCount; i++)
        {
            int v = BitConverter.ToInt32(inputInt32Bytes, i * 4);
            inputFloats[i] = (float)v;
        }

        var expectedBytes = await http.GetByteArrayAsync("references/movenet-lightning/cat_output.bin");
        var expected = new float[expectedBytes.Length / 4];
        Buffer.BlockCopy(expectedBytes, 0, expected, 0, expectedBytes.Length);

        using var session = await InferenceSession.CreateFromFileAsync(
            accelerator, http, "models/movenet-lightning/model.onnx");
        Console.WriteLine($"[MoveNet-Ref] session-init int-tensor count = {SpawnDev.ILGPU.ML.Graph.GraphExecutor.LastIntegerTensorCount}");
        using var inputBuf = accelerator.Allocate1D(inputFloats);
        var inputTensor = new Tensor(inputBuf.View, new[] { 1, 192, 192, 3 });

        var outputs = await session.RunAsync(new Dictionary<string, Tensor>
        {
            [session.InputNames[0]] = inputTensor
        });
        Console.WriteLine($"[MoveNet-Ref] run integer-Div count (TruncInPlace fires) = {SpawnDev.ILGPU.ML.Graph.GraphExecutor.LastRunIntegerDivCount}");

        var output = outputs[session.OutputNames[0]];
        int elems = Math.Min(output.ElementCount, expected.Length);
        using var readBuf = accelerator.Allocate1D<float>(elems);
        new ElementWiseKernels(accelerator).Scale(output.Data.SubView(0, elems), readBuf.View, elems, 1f);
        await accelerator.SynchronizeAsync();
        var actual = await readBuf.CopyToHostAsync<float>(0, elems);

        // Per-keypoint diff diagnostic - prints the first 5 keypoints so failures surface
        // which keypoints diverge and by how much. Useful when refining downstream pipeline.
        Console.WriteLine($"[MoveNet-Ref] Per-keypoint comparison (ORT 1.24.3 vs SpawnDev.ILGPU.ML, cat image):");
        for (int k = 0; k < 17; k++)
        {
            float yA = actual[k * 3 + 0], xA = actual[k * 3 + 1], cA = actual[k * 3 + 2];
            float yE = expected[k * 3 + 0], xE = expected[k * 3 + 1], cE = expected[k * 3 + 2];
            Console.WriteLine($"  kp {k,2}  ORT: y={yE:F4} x={xE:F4} c={cE:F4}   us: y={yA:F4} x={xA:F4} c={cA:F4}   d=({MathF.Abs(yA-yE):F4},{MathF.Abs(xA-xE):F4},{MathF.Abs(cA-cE):F4})");
        }

        // Strict-ish threshold: MoveNet outputs normalized coords in [0,1] and conf in [0,1],
        // so abs differences should be small. ORT runs FP32, our pipeline runs FP32 with
        // slightly different reduction orderings - tolerate up to 0.02 mean diff. If we're
        // bit-exact that's even better, but small drift is acceptable for floating-point
        // associativity differences across reduction orderings on GPU.
        try { AssertReferenceMatch(actual, expected, 0.02f, "MoveNet-Lightning vs ORT 1.24.3"); }
        catch (Exception ex)
        {
            // Compact per-keypoint diff so the failure message tells us WHERE the
            // drift is, not just that it exists. 17 keypoints * 3 values = 51 floats.
            var perKp = new System.Text.StringBuilder();
            for (int k = 0; k < 17; k++)
            {
                float yA = actual[k * 3 + 0], xA = actual[k * 3 + 1], cA = actual[k * 3 + 2];
                float yE = expected[k * 3 + 0], xE = expected[k * 3 + 1], cE = expected[k * 3 + 2];
                perKp.Append($"kp{k}({yA:F3}/{yE:F3},{xA:F3}/{xE:F3},{cA:F3}/{cE:F3}) ");
            }
            throw new Exception(
                $"{ex.Message} || diag: int-tensor-count={SpawnDev.ILGPU.ML.Graph.GraphExecutor.LastIntegerTensorCount}, " +
                $"int-Div-trunc-fired={SpawnDev.ILGPU.ML.Graph.GraphExecutor.LastRunIntegerDivCount}, " +
                $"init-dtypes={SpawnDev.ILGPU.ML.Graph.GraphExecutor.LastInitializerDataTypesCount} || " +
                $"per-kp (us/ort): {perKp}");
        }
        Console.WriteLine("[MoveNet-Ref] PASS");
    });

